CREATE POLICY "videos readable by authenticated" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'videos');
CREATE POLICY "videos insert own folder" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'videos' AND (storage.foldername(name))[1] = 'reels' AND (storage.foldername(name))[2] = auth.uid()::text);
CREATE POLICY "videos update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'videos' AND (storage.foldername(name))[2] = auth.uid()::text) WITH CHECK (bucket_id = 'videos' AND (storage.foldername(name))[2] = auth.uid()::text);
CREATE POLICY "videos delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'videos' AND (storage.foldername(name))[2] = auth.uid()::text);